from taf.analyzer.iperf_throughput.cell import TransferCell, BandwidthCell, LostTotalDatagramsCell, BitrateCell
from taf.analyzer.iperf_throughput.factory import (ServerThroughputFactory,
                                                   ClientThroughputFactory,
                                                   Iperf3UDPClientThroughputFactory,
                                                   Iperf3TCPClientThroughputFactory,
                                                   Iperf3ServerThroughputFactory)


class IperfThroughput(object):

    @staticmethod
    def create_iperf_server_udp_throughput(log, column=None, throughput_records_output=None, time_range=None):
        """
        Create throughput instance for iperf2 server side udp log
        This throughput will only calculate the value per connection
        if there are multiple connections, accumulation of multiple connections per second will not be care

        :param log: iperf file path
        :type log: str
        :param column: (optional) the column for comparison in log, 'bandwidth' by default, 'transfer' and 'datagrams'
        are options
        :type column: str
        :param throughput_records_output: (optional) throughput records output file path
        :type throughput_records_output: str
        :param time_range: (optional) time range of records which will be involved in calculation
        :type time_range: tuple[float]
        :return: Throughput class instance
        """
        support_columns = [TransferCell.name(), BandwidthCell.name(), LostTotalDatagramsCell.name()]
        column = IperfThroughput._refine_column(column, support_columns, default=BandwidthCell)
        factory = ServerThroughputFactory()
        if time_range:
            time_range = tuple(time_range)
        return factory.create(log, column, throughput_records_output, time_range=time_range)

